python
def positiveTraysProofStrip(readings):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return out


java
class Solution {
  public int[] positiveTraysProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
